using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Windows.Forms;
namespace Ara {
 public static class QrNowSleepTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static State New(){var s=State.New();s.GetDay(DateTime.Today).Wake=DateTime.Today.AddHours(8);GridEngine.Ensure(s,s.Days[0]);return s;}
  static CellBlock Fourth(State s,int delay,int count=3){var d=s.Days[0];var source=d.GridBase.Single(x=>x.MealId=="b15");var r=source.Copy();r.Id="actual-fourth";r.Start=r.Start.AddMinutes(delay);r.Count=count;r.Score=2;d.Records.Add(r);return r;}
  public static void Run(Action<string,Action> check,string dir){
   check("sleep floor: removing yogurt recovers at most ninety minutes with a normal half-hour fourth meal",()=>{foreach(int delay in new[]{30,60,90,120,180,300}){var s=New();var d=s.Days[0];var fourth=Fourth(s,delay);var p=GridEngine.Build(s,d);DateTime expected=new[]{Adaptive.Target(s,d),fourth.End.AddHours(2)}.Max();Assert(p.Blocks.Any(x=>x.MealId=="b16")== (delay<=50),"yogurt retained when it fits before sleep");Assert(Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==expected,"sleep floor at delay "+delay);Assert(p.Overflow==Math.Max(0,delay-90),"unrecoverable delay "+delay);Assert(fourth.Score==2&&d.Records.Count==1,"actual facts retained");}});
   check("sleep floor: actual fourth meal duration and adjacent score fragments determine its true end",()=>{var s=New();var d=s.Days[0];var fourth=Fourth(s,120,1);var continuation=fourth.Copy();continuation.Id="score-fragment";continuation.MealId="";continuation.Start=fourth.End;continuation.Count=5;continuation.Score=4;d.Records.Add(continuation);var p=GridEngine.Build(s,d);Assert(Adaptive.FourthMealEnd(d,p)==continuation.End,"full eating duration");Assert(Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==continuation.End.AddHours(2)&&p.Overflow==60,"sixty minutes unavoidable");Assert(GridEngine.Total(d)==22,"split scores unchanged");});
   check("sleep floor: even an eaten fifth meal cannot move sleep before fourth-meal end plus two hours",()=>{var s=New();var d=s.Days[0];var fourth=Fourth(s,0,18);var yogurt=d.GridBase.Single(x=>x.MealId=="b16").Copy();yogurt.Id="eaten-yogurt";d.Records.Add(yogurt);var p=GridEngine.Build(s,d);Assert(Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)==fourth.End.AddHours(2)&&p.Overflow==60,"two-hour floor wins");Assert(p.Blocks.Any(x=>x.MealId=="b16")&&d.Records.Count==2,"eaten fifth retained");});
   check("now marker: midnight and ten-minute rollover never alter the independent selection",()=>{using(var b=new Timetable()){var origin=new DateTime(2026,10,14);b.SetData(origin,new List<CellBlock>(),new List<CellBlock>());b.SetSelection(new CellSelection{Lane=1,First=90,Last=95});var selected=b.Selection;b.SetCurrentTime(origin.AddDays(1).AddMinutes(5));Assert(b.CurrentIndex==144&&object.ReferenceEquals(selected,b.Selection),"midnight current marker independent");b.SetCurrentTime(origin.AddDays(1).AddMinutes(10));Assert(b.CurrentIndex==145&&b.Selection.First==90,"rollover independent");b.SetCurrentTime(origin.AddDays(-1));Assert(b.CurrentIndex==-1,"outside date hidden");}});
   check("now marker: light and dark timeline draw subtle current dots in both lanes",()=>{foreach(bool dark in new[]{false,true}){Theme.Set(dark);using(var form=new Form{Size=new Size(900,650)})using(var b=new Timetable()){form.Controls.Add(b);form.Show();Application.DoEvents();var origin=DateTime.Today;b.SetData(origin,new List<CellBlock>(),new List<CellBlock>());b.SetCurrentTime(origin.AddHours(10).AddMinutes(23));b.SetSelection(new CellSelection{Lane=1,First=63,Last=65});b.Jump(origin.AddHours(10));using(var image=new Bitmap(b.Width,b.Height)){b.DrawToBitmap(image,new Rectangle(Point.Empty,b.Size));Color expected=dark?Color.FromArgb(185,160,100):Color.FromArgb(162,131,60);for(int lane=0;lane<2;lane++){var r=b.CellRect(lane,62);Assert(image.GetPixel(r.Right-7,r.Y+7).ToArgb()==expected.ToArgb(),"current dot in each lane");}image.Save(Path.Combine(dir,dark?"now-dark-pc.png":"now-light-pc.png"));}form.Close();}}});
   check("QR: local generation, private address payload and HTTP PNG require no pairing secret",()=>{var s=New();using(var f=new MainForm(new Store(Path.Combine(dir,"qr-ui.json")),s,true)){f.Show();Application.DoEvents();f.PhoneServer.Dispose();f.PhoneServer=new MobileServer(f,18765);f.PhoneServer.Start(false);var response=f.PhoneServer.Dispatch("GET","/connect-qr.png",new Dictionary<string,string>{{"host","127.0.0.1:18765"}},new byte[0],"127.0.0.1");Assert(response.status==200&&response.type=="image/png"&&response.body.Length>200,"PNG route available");using(var dialog=f.CreatePhoneDialog()){dialog.Show();Application.DoEvents();var picture=dialog.Controls.OfType<PictureBox>().Single();Assert(picture.Image!=null&&picture.Image.Width>200,"QR visible");using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(Point.Empty,dialog.Size));image.Save(Path.Combine(dir,"qr-connect-pc.png"));}dialog.Close();}File.WriteAllBytes(Path.Combine(dir,"qr-decode.png"),PhoneQr.Png("http://192.168.0.2:8765/download"));Assert(!PhoneQr.Url(f.PhoneServer).Contains(f.PhoneServer.Token)&&!PhoneQr.Url(f.PhoneServer).Contains(f.PhoneServer.Code),"QR contains only address");f.Quit();}});
  }
 }
}
